minimalRepro.script:
import {runExternal,withProcessBudget} from '/tmp/loomake-quality-after-merge/packages/kit/dist/index.js';
import {existsSync,rmSync,writeFileSync} from 'node:fs';
const base='/tmp/quality-supervisor-startup-probe';
const rows=[];
for(const delayed of [false,true]) {
 const marker=base+'/target-'+delayed;rmSync(marker,{force:true});
 const started=performance.now();let result,error;
 try {result=withProcessBudget({timeoutMs:150},()=>runExternal(process.execPath,['-e',`require('node:fs').writeFileSync(${JSON.stringify(marker)},'started')`],{env:{...process.env,...(delayed?{NODE_OPTIONS:'--require='+base+'/delay.cjs'}:{})}}));}
 catch(e){error={name:e.constructor.name,kind:e.kind,message:e.message};}
 rows.push({delayed,elapsedMs:performance.now()-started,result,error,targetStarted:existsSync(marker)});
}
writeFileSync(base+'/results.json',JSON.stringify({node:process.version,platform:process.platform,rows},null,2));console.log(JSON.stringify(rows));
